settings.liquid:
{%- assign cecha1 = product.metafields.custom.next_cecha_1 -%}
{%- assign cecha2 = product.metafields.custom.next_cecha_2 -%}
{%- assign cecha3 = product.metafields.custom.next_cecha_3 -%}

{%- if cecha1 != blank or cecha2 != blank or cecha3 != blank -%}
<div class="notebook-features-container">
  {%- if cecha1 != blank -%}<div class="notebook-row"><div class="arrow-container"><svg class="sketch-arrow" viewBox="0 0 50 50" fill="none" stroke="currentColor" stroke-width="3"><path d="M5 25 C 10 23, 15 27, 20 25 S 30 23, 35 25 S 40 27, 45 25" stroke-linecap="round"/><path d="M35 15 Q 43 23, 45 25 Q 43 27, 35 35" stroke-linecap="round"/></svg></div><div class="notebook-text">{{ cecha1 | metafield_tag }}</div></div>{%- endif -%}
  {%- if cecha2 != blank -%}<div class="notebook-row"><div class="arrow-container"><svg class="sketch-arrow" viewBox="0 0 50 50" fill="none" stroke="currentColor" stroke-width="3"><path d="M5 25 C 10 23, 15 27, 20 25 S 30 23, 35 25 S 40 27, 45 25" stroke-linecap="round"/><path d="M35 15 Q 43 23, 45 25 Q 43 27, 35 35" stroke-linecap="round"/></svg></div><div class="notebook-text">{{ cecha2 | metafield_tag }}</div></div>{%- endif -%}
  {%- if cecha3 != blank -%}<div class="notebook-row"><div class="arrow-container"><svg class="sketch-arrow" viewBox="0 0 50 50" fill="none" stroke="currentColor" stroke-width="3"><path d="M5 25 C 10 23, 15 27, 20 25 S 30 23, 35 25 S 40 27, 45 25" stroke-linecap="round"/><path d="M35 15 Q 43 23, 45 25 Q 43 27, 35 35" stroke-linecap="round"/></svg></div><div class="notebook-text">{{ cecha3 | metafield_tag }}</div></div>{%- endif -%}
</div>

<style>
  @import url('https://fonts.googleapis.com/css2?family=Caveat:wght@500;700&display=swap');

  :root { --nb-grid: rgba(160,200,240,0.3); --nb-ink: #1e3a8a; --nb-margin: #ffb3b3; }

  body.alt-vibe {
    --nb-grid: rgba(230, 211, 90, 0.4); 
    --nb-ink: #912c52;                 
    --nb-margin: #9DD3C9;              
    --nb-neon: #bfff00; 
  }

  /* WYMUSZENIE TŁA I ATC */
  body.alt-vibe .hdt-container-full { background-color: #FFF18C !important; background-image: none !important; --hdt-color-background: #FFF18C !important; }
  body.alt-vibe .main-atc-button { background-color: #EDB1CA !important; color: #000 !important; }
  body.alt-vibe .main-atc-button span { color: #000 !important; }

  .notebook-features-container {
    background-color: #fdfdfd;
    background-image: linear-gradient(90deg, transparent 49px, var(--nb-margin) 50px, var(--nb-margin) 51px, transparent 52px), linear-gradient(90deg, var(--nb-grid) 1px, transparent 1px), linear-gradient(var(--nb-grid) 1px, transparent 1px);
    background-size: 100% 100%, 24px 24px, 24px 24px;
    border: 1px solid #d1d5db; border-radius: 4px; padding: 24px 20px 24px 65px; margin: 20px 0;
    display: flex; flex-direction: column; transition: 0.4s;
  }

  .notebook-row { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 24px; min-height: 24px; }
  .arrow-container { flex-shrink: 0; height: 24px; display: flex; align-items: center; }
  .sketch-arrow { width: 26px; height: 26px; color: var(--nb-ink); }

  .notebook-text {
    font-family: 'Caveat', cursive; font-size: 24px; color: var(--nb-ink);
    line-height: 24px; word-break: break-word;
  }
  .notebook-text p { margin: 0 !important; line-height: 24px !important; }

  /* ZAKREŚLACZ FIX - TEKST JUŻ NIE NACHODZI */
  .notebook-text strong, .notebook-text b {
    font-weight: 700; color: var(--nb-ink); text-decoration: none;
    display: inline; border-bottom: 2px solid #ef4444; transition: 0.2s;
  }

  body.alt-vibe .notebook-text strong, body.alt-vibe .notebook-text b {
    border-bottom: none;
    box-shadow: inset 0 -11px 0 0 var(--nb-neon); /* Zakreślacz pod tekstem */
    padding: 0 2px;
    line-height: inherit !important;
  }

  @media (max-width: 768px) {
    .notebook-features-container { background-size: 100% 100%, 22px 22px, 22px 22px; padding: 22px 12px 22px 55px; background-image: linear-gradient(90deg, transparent 44px, var(--nb-margin) 45px, var(--nb-margin) 46px, transparent 47px), linear-gradient(90deg, var(--nb-grid) 1px, transparent 1px), linear-gradient(var(--nb-grid) 1px, transparent 1px); }
    .notebook-text { font-size: 20px; line-height: 22px; }
    .notebook-text p { line-height: 22px !important; }
    body.alt-vibe .notebook-text strong, body.alt-vibe .notebook-text b { box-shadow: inset 0 -9px 0 0 var(--nb-neon); }
  }
</style>
{%- endif -%}

{%- comment -%} LOGIKA CENOWA {%- endcomment -%}
{%- liquid
  assign current_variant = product.selected_or_first_available_variant
  assign current_price = current_variant.price
  assign compare_price = current_variant.compare_at_price | default: 0
  assign suggested_price = product.metafields.custom.cena_sugerowana.value | default: 0

  # Obliczanie procentowych obniżek (tylko jeśli cena sprzedaży jest niższa od odniesienia)
  assign disc_suggested = 0
  if suggested_price > current_price
    assign diff = suggested_price | minus: current_price
    assign disc_suggested = diff | times: 100.0 | divided_by: suggested_price | round
  endif

  assign disc_compare = 0
  if compare_price > current_price
    assign diff = compare_price | minus: current_price
    assign disc_compare = diff | times: 100.0 | divided_by: compare_price | round
  endif

  # Pobieranie pojemności i obliczanie ceny za 100ml
  assign volume = product.metafields.custom.pojemnosc.value | default: 50 | remove: 'ml' | strip | plus: 0
  assign unit_price_100ml = current_price | times: 1.0 | divided_by: volume | times: 100

  # Promocja aktywna, jeśli cena jest niższa od którejkolwiek ceny odniesienia
  assign is_on_sale = false
  if suggested_price > current_price or compare_price > current_price
    assign is_on_sale = true
  endif

  assign newsletter_price = current_price | times: 0.85
-%}

<style>
  @import url('https://fonts.googleapis.com/css2?family=Barlow:wght@400;600;700&family=Poppins:wght@400;500&display=swap');
  .p-section-final { font-family: 'Barlow', sans-serif; color: #1A1A1A; max-width: 550px; margin: 10px 0; }
  .p-flex-container { display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; }
  .p-price-row { display: flex; align-items: center; gap: 10px; line-height: 1; margin-bottom: 8px; }
  .p-main-val { font-size: 32px; font-weight: 700; color: #000; }
  .p-main-val.is-sale { color: #D32F2F; }

  .p-sale-badge { background-color: #D32F2F; color: #fff; font-size: 11px; font-weight: 700; padding: 3px 8px; border-radius: 3px; text-transform: uppercase; }

  .p-unit-info { font-size: 16px; color: #000; font-weight: 500; margin-top: 5px; }
  .p-unit-info strong { font-weight: 700; }

  .p-ref-price { font-size: 13px; color: #868686; margin-top: 6px; line-height: 1.5; }
  .p-ref-val { font-weight: 600; color: #000; }
  .p-disc-val { color: #D32F2F; font-weight: 600; }

  .p-newsletter-box { flex: 1; border-left: 1px solid #E0E0E0; padding-left: 20px; display: flex; flex-direction: column; justify-content: center; }
  .p-news-price { display: block; font-size: 16px; font-weight: 600; }
  .p-news-trigger { background: none; border: none; padding: 0; text-align: left; font-size: 11px; text-decoration: underline; cursor: pointer; color: #555; }
</style>

<div class="p-section-final">
  <div class="p-flex-container">
    <div class="p-info-main">
      <div class="p-price-row">
        <span class="p-main-val {% if is_on_sale %}is-sale{% endif %}">{{ current_price | money }}</span>
        {% if is_on_sale %}<span class="p-sale-badge">OKAZJA</span>{% endif %}
      </div>

      <div class="p-unit-info">
        Liczba sztuk w opakowaniu: <strong>{{ volume }} 
      </div>

      <div class="p-ref-price">
        {% if suggested_price > 0 %}
          <div>Cena sugerowana: <span class="p-ref-val">{{ suggested_price | money }}</span> 
            {% if disc_suggested > 0 %}<span class="p-disc-val">(-{{ disc_suggested }}%)</span>{% endif %}
          </div>
        {% endif %}
        {% if compare_price > 0 %}
          <div>Najniższa cena z 30 dni: <span class="p-ref-val">{{ compare_price | money }}</span> 
            {% if disc_compare > 0 %}<span class="p-disc-val">(-{{ disc_compare }}%)</span>{% endif %}
          </div>
        {% endif %}
      </div>
    </div>

    {% unless is_on_sale %}
      <div class="p-newsletter-box">
        <span class="p-news-price">{{ newsletter_price | money }} z kodem</span>
        <button type="button" class="p-news-trigger" onclick="openKlaviyoForm()">Zapisz się do newslettera i odbierz kod</button>
      </div>
    {% endunless %}
  </div>
</div>

<script>
  function openKlaviyoForm() {
    if (window._klOnsite) { window._klOnsite.push(['openForm', 'WCWzaD']); }
  }
</script>

{%- liquid
  assign upsell_products = product.metafields.custom.upsell.value
-%}

{%- if upsell_products != blank -%}
<div class="routines-upsell-wrapper" onclick="openRoutinesModal()">
  <div class="routines-pill-bar">
    <div class="routines-icon-stack">
      {%- for item in upsell_products limit: 5 -%}
        <img src="{{ item.featured_media | image_url: width: 150 }}" 
             class="routines-rotating-icon {% if forloop.first %}is-visible{% endif %}" 
             alt="upsell icon">
      {%- endfor -%}
    </div>
    <div class="routines-text-content">
      <span class="routines-label-title">Świetnie pasuje do pozostałych produktów NEXT GEN</span>
      <span class="routines-label-sub">Dobierz do swojej pielęgnacji</span>
    </div>
    <div class="routines-arrow-icon">
      <svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18l6-6-6-6"/></svg>
    </div>
  </div>
</div>

<div id="RoutinesUpsellModal" class="routines-modal-overlay">
  <div class="fit-modal-backdrop" onclick="closeRoutinesModal()"></div>
  <div class="routines-modal-container">
    <button class="routines-modal-close" onclick="closeRoutinesModal()">✕</button>

    <div class="routines-modal-header">
      <h3>Dodaj do swojej pielęgnacji</h3>
    </div>

    <div class="routines-products-grid">
      {%- for item in upsell_products -%}
        <div class="routines-product-card">
          <div class="routines-card-media">
             <a href="{{ item.url }}">
              <img src="{{ item.featured_media | image_url: width: 400 }}" alt="{{ item.title }}">
             </a>
          </div>

          <div class="routines-card-info">
            <h3 class="routines-card-title">{{ item.title }}</h3>
            <div class="routines-card-price">{{ item.price | money }}</div>

            <button type="button" 
                    class="routines-atc-btn-3d" 
                    onclick="addUpsellToCart(this, '{{ item.first_available_variant.id }}')">
              <span class="btn-text">DODAJ DO KOSZYKA</span>
            </button>

            <a href="{{ item.url }}" class="routines-details-link">Zobacz szczegóły produktu</a>
          </div>
        </div>
      {%- endfor -%}
    </div>
  </div>
</div>

<style>
  @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&family=Barlow:wght@600&display=swap');

  /* --- TRIGGER BAR --- */
  .routines-upsell-wrapper { margin: 25px 0; width: 100%; font-family: 'Poppins', sans-serif; }
  .routines-pill-bar { 
    display: flex; align-items: center; padding: 15px 25px; 
    border: 1px solid #e2e2e2; border-radius: 60px; 
    background: #fff; cursor: pointer; transition: all 0.2s ease;
  }
  .routines-pill-bar:hover { border-color: #4E54F0; box-shadow: 0 4px 12px rgba(78, 84, 240, 0.1); }

  .routines-icon-stack { position: relative; width: 60px; height: 60px; margin-right: 20px; flex-shrink: 0; }
  .routines-rotating-icon { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: contain; opacity: 0; transition: opacity 0.5s ease; }
  .routines-rotating-icon.is-visible { opacity: 1; }

  .routines-text-content { display: flex; flex-direction: column; flex-grow: 1; }
  .routines-label-title { font-size: 16px; font-weight: 700; color: #000; line-height: 1.2; }
  .routines-label-sub { font-size: 13px; color: #888; margin-top: 2px; }
  .routines-arrow-icon { color: #4E54F0; margin-left: 10px; display: flex; align-items: center; }

  /* --- MODAL --- */
  .routines-modal-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; z-index: 10000; display: none; align-items: center; justify-content: center; font-family: 'Poppins', sans-serif; }
  .routines-modal-overlay.active { display: flex; }
  .fit-modal-backdrop { position: absolute; width: 100%; height: 100%; background: rgba(0,0,0,0.4); backdrop-filter: blur(6px); }
  .routines-modal-container { position: relative; width: 95%; max-width: 1250px; max-height: 85vh; padding: 40px 20px; overflow-y: auto; z-index: 10001; }
  .routines-modal-close { position: absolute; top: 0; right: 20px; border: none; background: #fff; width: 44px; height: 44px; border-radius: 50%; font-size: 20px; cursor: pointer; box-shadow: 0 4px 10px rgba(0,0,0,0.1); }

  /* NAGŁÓWEK: Barlow 25px */
  .routines-modal-header h3 { 
    text-align: center !important; 
    font-family: 'Barlow', sans-serif !important; 
    font-size: 25px !important; 
    margin-bottom: 30px !important; 
    font-weight: 600 !important; 
    color: #fff !important; 
    text-shadow: 0 2px 4px rgba(0,0,0,0.2); 
    text-transform: none !important;
  }

  /* --- KARTY PRODUKTÓW (LAYOUT) --- */
  .routines-products-grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 20px; }
  .routines-product-card { flex: 0 1 290px; display: flex; flex-direction: column; background: #fff; border: 1px solid #eee; border-radius: 24px; padding: 25px; box-shadow: 0 10px 30px rgba(0,0,0,0.05); overflow: hidden; }
  .routines-card-media { width: 100%; height: 150px; margin-bottom: 15px; display: flex; align-items: center; justify-content: center; overflow: hidden; }
  .routines-card-media img { max-width: 100% !important; max-height: 150px !important; width: auto !important; height: auto !important; object-fit: contain !important; }

  .routines-card-title { font-size: 15px; font-weight: 600; margin: 0 0 4px 0; color: #000; text-align: center; line-height: 1.4; }
  .routines-card-price { font-weight: 700; color: #4E54F0; font-size: 17px; margin: 0 0 20px 0; text-align: center; }

  /* PRZYCISK 3D */
  .routines-atc-btn-3d { 
    position: relative;
    background: #4E54F0 !important; color: white !important; 
    border: none; width: 100%; padding: 15px; border-radius: 50px; 
    font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 13px; 
    cursor: pointer; box-shadow: 0 5px 0 #3238b5; transition: all 0.1s ease; top: 0;
  }
  .routines-atc-btn-3d:active { top: 3px; box-shadow: 0 2px 0 #3238b5; }
  .routines-details-link { display: block; margin-top: 15px; font-size: 11px; color: #bbb; text-decoration: underline; text-align: center; }

  /* --- KARUZELA MOBILE --- */
  @media (max-width: 767px) {
    .routines-modal-container { padding: 40px 0 20px 0; width: 100%; }
    .routines-modal-header h3 { font-size: 20px !important; padding: 0 20px; }
    .routines-products-grid {
      flex-wrap: nowrap !important;
      justify-content: flex-start !important;
      overflow-x: auto !important;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding: 0 20px 20px 20px;
      gap: 15px;
      scrollbar-width: none;
    }
    .routines-products-grid::-webkit-scrollbar { display: none; }
    .routines-product-card { flex: 0 0 75% !important; scroll-snap-align: start; padding: 15px; border-radius: 18px; }
    .routines-icon-stack { width: 50px; height: 50px; margin-right: 12px; }
    .routines-label-title { font-size: 14px; }
    .routines-label-sub { font-size: 12px; }
  }
</style>

<script>
function openRoutinesModal() {
  document.getElementById('RoutinesUpsellModal').classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeRoutinesModal() {
  document.getElementById('RoutinesUpsellModal').classList.remove('active');
  document.body.style.overflow = '';
}

function addUpsellToCart(button, variantId) {
  let btnText = button.querySelector('.btn-text');
  const originalText = btnText.innerText;
  btnText.innerText = 'DODAJE...';
  button.disabled = true;

  fetch(window.Shopify.routes.root + 'cart/add.js', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ 'items': [{ 'id': variantId, 'quantity': 1 }] })
  })
  .then(response => response.json())
  .then(item => {
    btnText.innerText = 'DODANO! 👍';
    document.dispatchEvent(new CustomEvent('cart:updated', { detail: { cart: item } }));
    document.documentElement.dispatchEvent(new CustomEvent('cart:refresh', { bubbles: true }));

    const cartDrawer = document.querySelector('cart-drawer') || document.querySelector('#CartDrawer');
    if (cartDrawer && typeof cartDrawer.open === 'function') {
        setTimeout(() => { closeRoutinesModal(); cartDrawer.open(); }, 600);
    }
    setTimeout(() => { btnText.innerText = originalText; button.disabled = false; }, 2000);
  });
}

document.addEventListener('DOMContentLoaded', function() {
  const icons = document.querySelectorAll('.routines-rotating-icon');
  if (icons.length <= 1) return;
  let current = 0;
  setInterval(() => {
    icons[current].classList.remove('is-visible');
    current = (current + 1) % icons.length;
    icons[current].classList.add('is-visible');
  }, 2000);
});
</script>
{%- endif -%}
